mapper.select:
SELECT paf.id AS purchase_id, paf.order_number AS purchase_order_number,
req.real_required AS 需求总数,
COALESCE(in_cnt.in_qty, 0) AS 入库数量, COALESCE(mrr.concession_qty, 0) AS 让步接收数量, COALESCE(mrr.return_continue_qty, 0) AS 退货继续采购数量, COALESCE(mrr.return_no_continue_qty, 0) AS 退货不继续采购数量,
( COALESCE(in_cnt.in_qty, 0) + COALESCE(mrr.concession_qty, 0) + COALESCE(mrr.return_no_continue_qty, 0) ) AS 已转换数,
CASE WHEN req.real_required = COALESCE(in_cnt.in_qty, 0) + COALESCE(mrr.concession_qty, 0) + COALESCE(mrr.return_no_continue_qty, 0) THEN '已完成' WHEN COALESCE(in_cnt.in_qty, 0) + COALESCE(mrr.concession_qty, 0) + COALESCE(mrr.return_no_continue_qty, 0) = 0 THEN '未开始' WHEN req.real_required > COALESCE(in_cnt.in_qty, 0) + COALESCE(mrr.concession_qty, 0) + COALESCE(mrr.return_no_continue_qty, 0) THEN '进行中' ELSE '超额完成' END AS complete_status
FROM application_form paf
/* ===== 1. 采购需求 ===== */ JOIN ( SELECT application_id, SUM(app_number) AS real_required FROM application_content WHERE application_id = #{lastAppFormId} GROUP BY application_id ) req ON paf.id = req.application_id
/* ===== 2. ✅ 入库数量（最终转换结果）===== */ LEFT JOIN ( SELECT SUM(ac.app_number) AS in_qty FROM application_content ac WHERE ac.application_id IN ( SELECT r.new_app_form_id FROM relationship r WHERE r.old_app_form_id IN ( SELECT DISTINCT r2.new_app_form_id FROM relationship r2 WHERE r2.old_app_form_id = #{lastAppFormId} ) AND r.new_app_form_id IN ( SELECT id FROM application_form WHERE sort = 5 ) ) ) in_cnt ON 1 = 1
/* ===== 3. 异常数量（质检单）===== */ LEFT JOIN ( SELECT 7734 AS purchase_id, SUM(CASE WHEN handle_type = 2 THEN return_qty ELSE 0 END) AS concession_qty, SUM(CASE WHEN handle_type = 1 AND continue_purchase = 1 THEN return_qty ELSE 0 END) AS return_continue_qty, SUM(CASE WHEN handle_type = 1 AND continue_purchase = 0 THEN return_qty ELSE 0 END) AS return_no_continue_qty FROM material_return_receive mrr WHERE mrr.application_id IN ( SELECT DISTINCT r.new_app_form_id FROM relationship r WHERE r.old_app_form_id IN ( SELECT DISTINCT r2.new_app_form_id FROM relationship r2 WHERE r2.old_app_form_id = #{lastAppFormId} ) ) ) mrr ON 1 = 1
WHERE paf.id = #{lastAppFormId};
